fun launch10000Thread(){
    var counter = 0
    try {
        repeat (100_000) {
            thread {
                sleep(1_000L)
                print(".")
            }
            ++counter
        }
    } finally {
        logger.info("Launched $counter")
    }
}


fun launch10000CoroutineWithSleep() {
    runBlocking {
        var counter = 0
            try {
                repeat(100_000) {
                    launch {
                        sleep(1_000L)
                        print(".")
                    }
                    ++counter
                }
            } finally {
                logger.info("Launched $counter")
            }

    }
}
    fun launch10000CoroutineWithDelay() {
        runBlocking {
            var counter = 0
                try {
                    repeat(100_000) {
                        launch {
                            delay(1_000.milliseconds)
                            print(".")
                        }
                        ++counter
                    }
                } finally {
                    logger.info("Launched $counter")
                }

        }
    }

